// Post-processes `drizzle-kit pull` output: keeps schema.ts / relations.ts, drops the migration
// artefacts (Drizzle never owns migrations here) and stamps a "generated" banner.
import { readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = fileURLToPath(new URL('../src/generated/', import.meta.url));
const banner =
  '// GENERATED by `pnpm db:pull` (drizzle-kit introspection of contracts/db/schema.sql). Do not edit.\n';

for (const entry of await readdir(dir, { withFileTypes: true })) {
  const path = join(dir, entry.name);
  if (entry.isDirectory() || entry.name.endsWith('.sql')) {
    await rm(path, { recursive: true, force: true });
  } else if (entry.name.endsWith('.ts')) {
    const src = await readFile(path, 'utf8');
    if (!src.startsWith(banner)) await writeFile(path, banner + src);
  }
}
console.warn('db: introspected schema written to src/generated');
